import{_ as o,r as n,o as p,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"{% component %} - October CMS - 4.x","titleTemplate":false,"description":"Twig Tag","frontmatter":{"subtitle":"Twig Tag"},"headers":[{"level":2,"title":"Variables","slug":"variables","link":"#variables","children":[]},{"level":2,"title":"AJAX Updates","slug":"ajax-updates","link":"#ajax-updates","children":[]},{"level":2,"title":"Customizing Components","slug":"customizing-components","link":"#customizing-components","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/markup/tag/component.md","filePath":"4.x/markup/tag/component.md"}'),u={name:"4.x/markup/tag/component.md"};function r(d,a,m,g,k,h){const t=n("pre-heading"),e=n("post-heading");return p(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"{% component %}",-1)),s(e),a[1]||(a[1]=i(`<p>The <code>{% component %}</code> tag will parse the default markup content for a <a href="./../../cms/themes/components.html">CMS component</a> and display it on the page. Not all components provide default markup, the documentation for the plugin will guide in the correct usage.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>blogPosts<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>This will render the component partial with a fixed name of <strong>default.htm</strong> and is essentially an alias for the following:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>blogPosts::default<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="variables"><a href="#variables" class="header-anchor">#</a> Variables</h2><p>Some components support passing variables to them at render time.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>blogPosts<span class="token punctuation">&quot;</span></span> postsPerPage<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>5<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="ajax-updates"><a href="#ajax-updates" class="header-anchor">#</a> AJAX Updates</h2><p>To update the component markup with an <a href="./../../cms/ajax/introduction.html">AJAX request</a>, the output can be wrapped in an <a href="./ajax-partial.html">AJAX partial</a> so it can be targeted by the <code>_self</code> update, including <a href="./../../cms/ajax/update-partials.html">from within the component itself</a>. Enable this by setting <code>ajaxPartial</code> to <code>true</code> in the <a href="./../../extend/cms-components.html">component class definition</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">componentDetails</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// ...</span>
        <span class="token string single-quoted-string">&#39;ajaxPartial&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>With this enabled, the <code>{% component %}</code> tag wraps its output so that AJAX handlers can update the component in place.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">component</span> <span class="token string"><span class="token punctuation">&quot;</span>contactForm<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>For example, the component markup below submits to its own handler and updates itself with the result.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>contactForm::onSave<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ _self: true }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token comment">&lt;!-- ... --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="customizing-components"><a href="#customizing-components" class="header-anchor">#</a> Customizing Components</h2><p>In most cases the <code>{% component %}</code> tag is not needed and the markup is provided as a usage example for the component API. Components are intended to be customized, this can be done in two ways:</p><ol><li>Moving the default markup to a partial</li><li>Overriding component partials using the theme</li></ol><p>The <a href="./../../cms/themes/components.html">CMS Components article</a> outlines the process of customizing default markup.</p><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../cms/themes/components.html">CMS Components</a></li></ul></div>`,20))])}const v=o(u,[["render",r]]);export{w as __pageData,v as default};
